import{c as t,S as a,j as r,m as d}from"./chunks/framework.DBSVVeOL.js";const f=JSON.parse('{"title":"Feature Coverage","description":"","frontmatter":{},"headers":[],"relativePath":"feature-coverage.md","filePath":"feature-coverage.md","lastUpdated":null}'),l={name:"feature-coverage.md"};function s(n,e,o,i,c,u){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="Feature-Coverage" tabindex="-1">Feature Coverage <a class="header-anchor" href="#Feature-Coverage" aria-label="Permalink to &quot;Feature Coverage {#Feature-Coverage}&quot;">​</a></h1><p>This page is the canonical feature coverage tracker for Natter.jl. It includes implementation notes, test coverage expectations, partial support, and intentionally omitted edge cases.</p><p>Statuses:</p><ul><li><p><code>Supported</code>: implemented for the normal production path and covered by unit or integration tests where practical.</p></li><li><p><code>Partial</code>: implemented for common paths, with documented gaps.</p></li><li><p><code>Planned</code>: intended for future work.</p></li><li><p><code>Not planned</code>: intentionally excluded.</p></li><li><p><code>Ignored as esoteric</code>: uncommon administrative surface that is documented but not prioritized.</p></li></ul><p>The normal test suite is server-free. Setting <code>NATTER_RUN_INTEGRATION=true</code> executes real <code>nats-server</code> tests; setting <code>NATTER_RUN_JETSTREAM=true</code> also executes JetStream and KeyValue tests.</p><h2 id="Core-NATS" tabindex="-1">Core NATS <a class="header-anchor" href="#Core-NATS" aria-label="Permalink to &quot;Core NATS {#Core-NATS}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">TCP transport</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Plain <code>nats://</code> connections.</td></tr><tr><td style="text-align:left;">TLS transport</td><td style="text-align:left;">Partial</td><td style="text-align:left;">CA/client cert/key options are available; broad platform verification still needs integration hardening.</td></tr><tr><td style="text-align:left;">WebSocket transport</td><td style="text-align:left;">Planned</td><td style="text-align:left;"><code>ws://</code> and <code>wss://</code> are not implemented yet; planned only if there is clear demand.</td></tr><tr><td style="text-align:left;">Connect handshake</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Includes typed token, user/password, NKEY, JWT, <code>.creds</code>, and callback authentication, client name, no echo, TLS requirements, and server INFO parsing.</td></tr><tr><td style="text-align:left;">INFO / CONNECT / PING / PONG</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Includes async INFO updates and ping-based flush.</td></tr><tr><td style="text-align:left;">PUB / HPUB / SUB / UNSUB</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Headers are negotiated from server INFO before advertising or emitting HPUB. Queue groups are included. Outbound writes use a size- and latency-bound buffered flusher, with explicit flush/ping forcing a transport flush.</td></tr><tr><td style="text-align:left;">Wildcard subscriptions</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>*</code> and terminal <code>&gt;</code> subscriptions are validated. Publish subjects reject wildcards.</td></tr><tr><td style="text-align:left;">MSG / HMSG parser</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Streaming line/payload parser written from scratch.</td></tr><tr><td style="text-align:left;">Request/reply</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Uses a shared request inbox mux with per-request waiters and maps negotiated no-responder status to <code>NoRespondersError</code>.</td></tr><tr><td style="text-align:left;">Direct public API and task handles</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Direct calls are task-friendly; <code>_async</code> helpers return <code>NatterTask</code> for explicit handle-oriented code, and <code>fetch(handle)</code> returns the sync result or throws the same operation error that the synchronous API would throw.</td></tr><tr><td style="text-align:left;">No responders</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Advertised only when server INFO reports header support; status <code>503</code> replies become <code>NoRespondersError</code>.</td></tr><tr><td style="text-align:left;">Flush</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Drains buffered outbound writes and uses a ping/pong round trip for synchronization.</td></tr><tr><td style="text-align:left;">Drain</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Subscription and client drain are implemented with one overall timeout deadline, report cleanup failures, and are covered by unit and real-server tests.</td></tr><tr><td style="text-align:left;">Close</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Closes tasks and transport without further reconnects.</td></tr><tr><td style="text-align:left;">Reconnect</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Automatic reconnect is enabled by default with server pool, discovered URLs with stale-route pruning, backoff, subscription replay, pending buffer restore-on-failure, generation-bound background tasks, typed connection events, and optional reconnect-delay override callbacks. Publish replay is best-effort and should be treated as at-least-once for retained frames, not exactly-once: duplicate delivery is possible if a transport fails after partial server acceptance, and large frames that bypass the write buffer are not retained after a successful direct socket write. Use JetStream <code>msg_id</code> deduplication or idempotent application handling when duplicate effects are unacceptable. Real-server tests cover same-server reconnect and multi-URL failover through a local proxy; multi-node cluster chaos and auth failover coverage still need expansion.</td></tr><tr><td style="text-align:left;">Discovered servers</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Server-discovered URLs are retained for reconnects, and stale discovered routes are pruned on subsequent INFO updates.</td></tr><tr><td style="text-align:left;">Lame Duck Mode</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Async INFO with <code>ldm=true</code> triggers reconnect.</td></tr><tr><td style="text-align:left;">Server errors</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Permission violations are reported without reconnecting; repeated auth failures abort reconnect with auth-specific errors.</td></tr><tr><td style="text-align:left;">Max payload enforcement</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Uses server <code>max_payload</code> from INFO.</td></tr><tr><td style="text-align:left;">Slow consumer handling</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Per-subscription pending message/byte limits raise <code>SlowConsumerError</code> through <code>error_cb</code>.</td></tr><tr><td style="text-align:left;">Typed errors</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Common connection, protocol, auth, permission, buffer, timeout, slow consumer, and JetStream errors.</td></tr><tr><td style="text-align:left;">Optimized request inbox multiplexing</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Requests share one wildcard inbox subscription per client and clean waiters on timeout, reconnect, and close.</td></tr></tbody></table><h2 id="TLS-And-Security" tabindex="-1">TLS And Security <a class="header-anchor" href="#TLS-And-Security" aria-label="Permalink to &quot;TLS And Security {#TLS-And-Security}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Token auth</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>TokenAuth</code> or URL userinfo when <code>auth=NoAuth()</code>. Option tokens are stored in redacted wipeable buffers, and token values are redacted from <code>ConnectOptions</code> display including URL userinfo.</td></tr><tr><td style="text-align:left;">Username/password auth</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>UserPassAuth</code> or URL userinfo when <code>auth=NoAuth()</code>. Option passwords are stored in redacted wipeable buffers, and users/passwords are redacted from <code>ConnectOptions</code> display including URL userinfo.</td></tr><tr><td style="text-align:left;">NKEY auth</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>NKeyAuth</code> implements CONNECT nonce signing for public user NKEY plus callback and user seed-backed NKEY auth. NKEY seeds are stored in redacted wipeable buffers, path-loaded seed input buffers are wiped after CONNECT fields are derived, non-user NKEY prefixes are rejected locally, and unit tests cover CONNECT fields; CI real-server coverage runs through <code>NATTER_NKEY_AUTH_URL</code> and <code>NATTER_NKEY_AUTH_SEED</code>.</td></tr><tr><td style="text-align:left;">JWT credentials</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>JwtAuth</code> and <code>CredentialsAuth</code> implement CONNECT nonce signing for user JWT plus seed/callback and user credentials, including standard decorated <code>.creds</code> content. JWT and inline credentials are stored in redacted wipeable buffers, path-loaded auth input buffers are wiped after CONNECT fields are derived, and CONNECT serialization and <code>.creds</code> parsing are unit-tested; CI real-server coverage runs with generated NSC credentials through <code>NATTER_JWT_AUTH_URL</code> and <code>NATTER_JWT_AUTH_CREDENTIALS_PATH</code>.</td></tr><tr><td style="text-align:left;">Dynamic auth callback</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>CallbackAuth</code> receives <code>AuthRequest</code> after server <code>INFO</code> on initial connect and reconnect and must return a concrete static auth value. Callback return validation and request context are unit-tested.</td></tr><tr><td style="text-align:left;"><code>.creds</code> file parsing</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>CredentialsAuth</code> extracts the user JWT and NKEY seed from standard decorated credentials content without retaining the whole file as an immutable string.</td></tr><tr><td style="text-align:left;">TLS first handshake</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>tls://</code> uses TLS before INFO by default. <code>tls_first=true</code> enables it for other URLs and <code>tls_first=false</code> preserves INFO-first TLS upgrade behavior when needed.</td></tr><tr><td style="text-align:left;">INFO-first TLS upgrade</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Use <code>tls_first=false</code> for deployments that require it.</td></tr><tr><td style="text-align:left;">CA and client certificates</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>tls_ca_path</code>, <code>tls_cert_path</code>, and <code>tls_key_path</code>.</td></tr><tr><td style="text-align:left;">TLS certificate verification control</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Verification is enabled by default. IP-literal hosts match <code>iPAddress</code> subject alternative names, <code>tls_server_name</code> overrides SNI and certificate-name validation, and <code>tls_verify=false</code> intentionally disables peer certificate verification.</td></tr><tr><td style="text-align:left;">WebSocket custom headers</td><td style="text-align:left;">Planned</td><td style="text-align:left;">Depends on WebSocket transport.</td></tr></tbody></table><h2 id="JetStream" tabindex="-1">JetStream <a class="header-anchor" href="#JetStream" aria-label="Permalink to &quot;JetStream {#JetStream}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">JetStream context</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>jetstream(client)</code> creates a context.</td></tr><tr><td style="text-align:left;">Publish with ack</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Parses <code>PubAck</code> and API errors. <code>js_publish</code> exposes first-class options for msg-id, expected stream/sequence/msg-id/subject, per-message TTL, schedules, and no-responders retry.</td></tr><tr><td style="text-align:left;">Task handle helpers</td><td style="text-align:left;">Supported</td><td style="text-align:left;">JetStream management, publish, message get/delete, consumers, fetch, close, and ack operations have <code>_async</code> helpers returning <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;">Typed stream configs</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>StreamConfig</code> covers current stream schema fields with typed nested structs, enums, duration conversion, local subject/name/numeric validation, and raw <code>Dict</code> escape hatch using the same duration units for known fields.</td></tr><tr><td style="text-align:left;">Raw config dictionaries</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Escape hatch for newer server fields.</td></tr><tr><td style="text-align:left;">Stream create/update/info/list/names/purge/delete</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Common management APIs, including list pagination. Stream info returns typed config plus typed stream state.</td></tr><tr><td style="text-align:left;">Message get/delete</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Common API path, including sequence, last-by-subject, next-by-subject, and direct reads.</td></tr><tr><td style="text-align:left;">Typed consumer configs</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>ConsumerConfig</code> covers current consumer schema fields with typed enums, duration conversion, local subject/name/queue/numeric validation, and raw <code>Dict</code> escape hatch using the same duration units for known fields.</td></tr><tr><td style="text-align:left;">Consumer create/update/info/list/delete</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Common management APIs, including newer named consumer subjects and legacy durable subjects. <code>consumer_create</code> and <code>consumer_update</code> use strict server actions when supported; <code>consumer_create_or_update</code> is the explicit upsert API. Consumer info returns typed config, counters, sequence cursors, and push-bound state.</td></tr><tr><td style="text-align:left;">Pull subscribe/fetch/consume</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Durable and named consumers bind without mutation, validate supplied config fields, and recover from a concurrent matching strict-create conflict by binding; random ephemerals are strictly created and deleted on close. Bounded batch fetch, <code>max_bytes</code>, <code>no_wait</code>, idle heartbeat monitoring, threshold-refilled <code>messages</code>, callback <code>consume</code>, priority scheduling request fields, per-request reply correlation, expiration handling, reconnect-disconnect reporting, and JetStream status/control error mapping are covered. Continuous stream refill tracks buffered/requested client messages and bytes instead of only outstanding server request counters, and caps new pulls by <code>channel_size</code>, <code>max_bytes</code>, and <code>stop_after</code>. Only one active fetch or stream may use a pull subscription at a time. Pull requests are not replayed after reconnect; callers retry bounded fetches after <code>FetchDisconnectedError</code>, while streams surface errors through <code>wait(stream)</code>/<code>fetch(stream)</code>.</td></tr><tr><td style="text-align:left;">Push subscribe</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Common durable/ephemeral delivery works; durable and named consumers bind without mutation, validate supplied config fields, and recover from a concurrent matching strict-create conflict by rebinding to the existing deliver subject. Active non-queue push consumers reject a second bind; existing queue consumers require an explicit matching <code>queue</code>; queue groups can be supplied through <code>queue</code> or <code>deliver_group</code> for new consumers. Queue groups, callbacks, and manual or automatic acknowledgement are supported. Push status/control messages are handled internally, flow control requests and stalled-consumer heartbeats are answered internally, consumer deletion/leadership statuses and heartbeat sequence mismatches are reported through <code>error_cb</code>, and returned subscriptions are closable. Random ephemeral consumers are deleted on close.</td></tr><tr><td style="text-align:left;">Manual ack APIs</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>ack</code>, <code>ack_sync</code>, <code>nak</code>, <code>in_progress</code>, and <code>term</code>.</td></tr><tr><td style="text-align:left;">JetStream message metadata</td><td style="text-align:left;">Supported</td><td style="text-align:left;">V1 and domain-aware V2 ack metadata parsing.</td></tr><tr><td style="text-align:left;">Ordered consumers</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Public ordered-consumer helpers are still absent. KeyValue watch uses internal ordered ephemeral push consumers with flow control, heartbeat monitoring, sequence-gap detection, and automatic reset from the next stream sequence.</td></tr><tr><td style="text-align:left;">Flow control / heartbeats</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Pull fetch consumes status/control messages and monitors requested idle heartbeats. Non-queue push consumers hide idle heartbeats, report missed heartbeats and consumer sequence mismatches through <code>error_cb</code>, and answer flow-control requests plus stalled-consumer heartbeats internally.</td></tr><tr><td style="text-align:left;">Object Store</td><td style="text-align:left;">Planned</td><td style="text-align:left;">Not implemented in the first milestone.</td></tr><tr><td style="text-align:left;">Direct get</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>stream_message_get(...; direct=true)</code> supports sequence, last-by-subject, and next-by-subject direct reads. KeyValue stores remember <code>allow_direct</code> and use direct reads automatically.</td></tr><tr><td style="text-align:left;">Stream templates</td><td style="text-align:left;">Ignored as esoteric</td><td style="text-align:left;">Legacy/rare API surface.</td></tr><tr><td style="text-align:left;">Leader stepdown / peer removal</td><td style="text-align:left;">Ignored as esoteric</td><td style="text-align:left;">Administrative APIs are not prioritized for client v1.</td></tr></tbody></table><h2 id="KeyValue" tabindex="-1">KeyValue <a class="header-anchor" href="#KeyValue" aria-label="Permalink to &quot;KeyValue {#KeyValue}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Create/open/delete/status bucket</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Built on stream APIs and covered by real-server tests. <code>kv_create</code> exposes history, bucket TTL, max bucket bytes, max value size, storage, replicas, direct reads, compression, metadata, and delete-marker TTL; history is locally limited to 1 through 64. <code>kv_status</code> exposes values, history, TTL, bytes, storage, replicas, direct-read support, and backing stream info. Bucket operations accept per-call timeouts.</td></tr><tr><td style="text-align:left;">Get/put/create/update/delete/purge</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>kv_get</code> returns typed entries with key, value, revision, created timestamp, delta, and operation, including server TTL marker reasons. Put/create/update return the new KV revision. Revision checks use expected-last-subject-sequence headers, including create after delete/purge markers and guarded delete/purge operations. Put/create/update support per-key TTL headers; purge supports purge-marker TTL and marker cleanup. Common paths are covered by real-server tests. Missing/deleted keys and optimistic-write conflicts raise KV-specific errors. Key operations accept per-call timeouts.</td></tr><tr><td style="text-align:left;">Keys/history</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Common paths implemented with temporary consumer cleanup and looped fetches; history returns typed entries including delete and purge operations. Keys and history operations use one per-call timeout budget across consumer setup and fetch pagination.</td></tr><tr><td style="text-align:left;">Watch/watchall</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Callback and <code>KeyValueWatcher</code> channel APIs deliver typed entries through closable ordered push consumers. Default watch delivers last value per subject plus updates and sends an initial-done sentinel on channel watchers. Watch supports multiple filters, updates-only, history, ignore-deletes, metadata-only delivery, resume revision, and per-call setup timeout. Watch consumers use flow control, heartbeat monitoring, sequence-gap detection, and automatic reset from the next stream sequence. Broad chaos-tested recovery is still pending.</td></tr><tr><td style="text-align:left;">Direct get</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>kv_create(...; direct=true)</code> enables direct reads, <code>kv_open</code> detects existing direct buckets, and <code>kv_get</code> uses direct access by default when available.</td></tr><tr><td style="text-align:left;">Task handle helpers</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Bucket, status, key, history, keys, watch, and watcher close operations have <code>_async</code> helpers returning <code>NatterTask</code>.</td></tr></tbody></table><h2 id="Services-/-Micro" tabindex="-1">Services / Micro <a class="header-anchor" href="#Services-/-Micro" aria-label="Permalink to &quot;Services / Micro {#Services-/-Micro}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Service framework</td><td style="text-align:left;">Planned</td><td style="text-align:left;">Not implemented in the first milestone.</td></tr><tr><td style="text-align:left;">Endpoint discovery/stats</td><td style="text-align:left;">Planned</td><td style="text-align:left;">Depends on service framework.</td></tr></tbody></table><h2 id="Observability" tabindex="-1">Observability <a class="header-anchor" href="#Observability" aria-label="Permalink to &quot;Observability {#Observability}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Client stats</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Basic message/byte/reconnect counters.</td></tr><tr><td style="text-align:left;">Status callbacks</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Connected, disconnected, reconnected, closed, and error callbacks.</td></tr><tr><td style="text-align:left;">Structured logging</td><td style="text-align:left;">Planned</td><td style="text-align:left;">Current implementation uses callbacks and exceptions rather than a logging facade.</td></tr></tbody></table><h2 id="Explicitly-Missing-From-Initial-Coverage" tabindex="-1">Explicitly Missing From Initial Coverage <a class="header-anchor" href="#Explicitly-Missing-From-Initial-Coverage" aria-label="Permalink to &quot;Explicitly Missing From Initial Coverage {#Explicitly-Missing-From-Initial-Coverage}&quot;">​</a></h2><ul><li><p>WebSocket transport and WebSocket custom headers.</p></li><li><p>Object Store.</p></li><li><p>Services/micro framework.</p></li><li><p>Public ordered-consumer helpers outside KeyValue watch.</p></li><li><p>Dedicated JetStream publish batching and pending-window APIs beyond <code>NatterTask</code> concurrency and reconnect buffering.</p></li><li><p>Cluster chaos tests covering discovered route churn, auth failover, and failover under load.</p></li></ul>',19)])])}const g=t(l,[["render",s]]);export{f as __pageData,g as default};
